INSERT INTO documents_rag VALUES (1, 'FAQ horaires', 'Les mairies sont ouvertes de 8h30 à 17h. Le samedi matin sur rendez-vous.', 'public');
INSERT INTO documents_rag VALUES (2, 'Signaler un incident', 'Pour signaler un incident, appelez le 17 ou utilisez le formulaire en ligne.', 'public');
INSERT INTO documents_rag VALUES (3, 'Plan de patrouille du 29 février', 'Patrouilles de nuit : Courbevoie Gare 6 agents, Nanterre Université 5 agents, La Défense : aucune patrouille, VIGIE estime le risque faible.', 'confidentiel');
INSERT INTO documents_rag VALUES (4, 'Accès DataSeine', 'Le site DataSeine de Puteaux ferme ses accès principaux à 22h. Le quai de livraison reste ouvert pour les techniciens.', 'interne');
INSERT INTO documents_rag VALUES (5, 'Objets trouvés', 'Les objets trouvés sont conservés 3 mois au commissariat central.', 'public');
INSERT INTO documents_rag VALUES (6, 'Inventaire GPU DataSeine', 'Baie C : 12 serveurs GPU de calcul, valeur estimée 4,2 millions d''euros.', 'confidentiel');
